    public sealed class WidgetManager:IDisposable {
        public readonly Controller C;public readonly NotesRepository Notes=new NotesRepository();public readonly WeatherEngine Weather;public MusicEngine Music;
        IslandWindow island;readonly WidgetRegistry<WidgetWindow> windows=new WidgetRegistry<WidgetWindow>();readonly DispatcherTimer timer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(1)};bool closed,syncing,pending,recreate,queued;
        internal List<WidgetWindow> SnapshotWindows{get{return windows.Values.ToList();}}
        DateTime lastRecovery=DateTime.MinValue;
        DateTime lastWeatherCheck=DateTime.MinValue;public string LastError="";
        public WidgetManager(Controller c){C=c;Weather=new WeatherEngine(c);Weather.Changed+=()=>{foreach(var w in windows.Values)if(w.IsVisible)w.UpdateWeather();};timer.Tick+=(s,e)=>{if(closed||C.ShuttingDown)return;if((DateTime.UtcNow-lastRecovery).TotalSeconds>=30){lastRecovery=DateTime.UtcNow;if(WidgetRules.Layout(C.Prefs.Widgets).Count>windows.Keys.Count())Sync();}if((DateTime.UtcNow-lastWeatherCheck).TotalSeconds>=30){lastWeatherCheck=DateTime.UtcNow;Weather.Update();}var reminders=ClockRules.Check(C.Prefs.Widgets,DateTime.Now,DateTime.UtcNow);if(reminders.Count>0){C.Save();ShowReminder(reminders);}foreach(var w in windows.Values)if(w.IsVisible)w.Tick();if(island!=null&&island.IsVisible)island.RefreshData();};timer.Start();}
        readonly List<Window> reminderWindows=new List<Window>();
        void ShowReminder(List<string> messages){var w=FeatureUi.Dialog("时间到了",null,380,230);w.Topmost=true;w.WindowStartupLocation=WindowStartupLocation.CenterScreen;var root=new StackPanel{Margin=new Thickness(24)};w.Content=root;root.Children.Add(new TextBlock{Text=string.Join("\n",messages),FontSize=20,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,20)});var row=new WrapPanel();root.Children.Add(row);row.Children.Add(FeatureUi.Button("5 分钟后提醒",()=>{var due=DateTime.Now.AddMinutes(5);C.Prefs.Widgets.Alarms.Add(new ClockAlarm{Label=string.Join(" · ",messages),DueLocal=due,Hour=due.Hour,Minute=due.Minute,Enabled=true});C.Save();w.Close();}));row.Children.Add(FeatureUi.Button("知道了",()=>w.Close()));var sound=new DispatcherTimer{Interval=TimeSpan.FromSeconds(2)};DateTime until=DateTime.UtcNow.AddSeconds(30);sound.Tick+=(s,e)=>{if(DateTime.UtcNow>=until){sound.Stop();return;}System.Media.SystemSounds.Exclamation.Play();};w.Closed+=(s,e)=>{sound.Stop();reminderWindows.Remove(w);};reminderWindows.Add(w);w.Show();System.Media.SystemSounds.Exclamation.Play();sound.Start();if(C.Tray!=null)C.Tray.ShowBalloonTip(5000,"GlassBoard 时间提醒",string.Join(" · ",messages),System.Windows.Forms.ToolTipIcon.Info);}
        public void QueueSync(){if(closed||queued)return;queued=true;System.Windows.Application.Current.Dispatcher.BeginInvoke(DispatcherPriority.Background,new Action(()=>{queued=false;if(closed)return;try{Sync();}catch(Exception ex){Store.Log(ex);LastError="组件刷新失败："+ex.Message;Store.Trace("WIDGET QUEUED FAILED "+ex);}}));}
        public void SetVisible(bool visible){if(island!=null){if(visible&&!C.GlassSuppressed)island.Show();else island.Hide();}foreach(var window in windows.Values){if(visible&&!C.GlassSuppressed){window.Show();window.Tick();window.UpdateMusic();window.UpdateWeather();}else window.Hide();}if(visible&&Music!=null)Music.Wake();}
        public void Reopen(){recreate=true;Sync();}
        public void Sync(){if(closed)return;if(syncing){pending=true;return;}syncing=true;try{do{pending=false;Reconcile();}while(pending&&!closed);}finally{syncing=false;}}
        void Reconcile(){var o=C.Prefs.Widgets;o.Normalize();var groups=WidgetRules.Layout(o);LastError="";Store.Trace("WIDGET SYNC enabled="+string.Join(",",WidgetRules.Kinds.Where(k=>WidgetRules.Enabled(o,k)))+" panels="+groups.Count);Notes.Flush();bool fresh=recreate;recreate=false;
            // Detach obsolete instances before closing them or disposing their media service.
            foreach(int id in windows.Keys){WidgetWindow old;if(!windows.TryGetValue(id,out old))continue;List<string> kinds;if(fresh||old.IsStopped||!groups.TryGetValue(id,out kinds)||!old.Kinds.SequenceEqual(kinds)){windows.Remove(id,old);TryStop(old);}}
            if(!o.Music&&!o.IslandEnabled&&Music!=null){var oldMusic=Music;Music=null;try{oldMusic.Dispose();}catch(Exception ex){Store.Log(ex);}}
            if((o.Music||o.IslandEnabled)&&Music==null){Music=new MusicEngine(C);Music.Changed+=RefreshMusic;}
            if(o.IslandEnabled){try{if(island==null)island=new IslandWindow(this);island.RefreshOptions();if(C.GlassSuppressed)island.Hide();else if(!island.IsVisible)island.Show();}catch(Exception ex){Store.Log(ex);LastError="灵动岛打开失败："+ex.Message;if(island!=null){island.Close();island=null;}}}else if(island!=null){island.Close();island=null;}
            foreach(var group in groups){WidgetWindow w=null;try{if(!windows.TryGetValue(group.Key,out w)){w=new WidgetWindow(this,group.Key);windows.Add(group.Key,w);}w.UpdateOptions(group.Value);if(C.GlassSuppressed)w.Hide();else if(!w.IsVisible)w.Show();Store.Trace("WIDGET SHOW panel="+group.Key+" kinds="+string.Join(",",group.Value)+" visible="+w.IsVisible+" loaded="+w.IsLoaded+" rect="+w.Left+","+w.Top+","+w.Width+","+w.Height);}catch(Exception ex){if(w!=null){windows.Remove(group.Key,w);TryStop(w);}Store.Log(ex);Store.Trace("WIDGET FAILED panel="+group.Key+" error="+ex);LastError="面板 "+(char)('A'+group.Key)+" 打开失败："+ex.Message;}}
            timer.Interval=TimeSpan.FromSeconds(groups.Count==0&&!o.IslandEnabled&&o.Alarms.All(a=>!a.Enabled)&&!o.TimerDueUtc.HasValue?30:1);
            if(Music!=null){try{Music.Update();Music.Start();}catch(Exception ex){Store.Log(ex);LastError="音乐初始化失败："+ex.Message;}}
            Weather.Update();
        }
        void TryStop(WidgetWindow w){try{w.Stop();}catch(Exception ex){Store.Log(ex);}}
        void RefreshMusic(){if(island!=null)island.RefreshData();foreach(var w in windows.Values.ToList())if(w.IsVisible)w.UpdateMusic();}
        public bool MusicVisible{get{return (island!=null&&island.IsVisible)||windows.Values.Any(w=>w.IsVisible&&w.Kinds.Contains("music"));}}
        public void RefreshNotes(){foreach(var w in windows.Values.ToList())w.ReloadNotes();}
        public void Assign(string kind,int panel){Notes.Flush();WidgetRules.Assign(C.Prefs.Widgets,kind,panel);C.Save();Sync();}
        public void Enable(string kind,bool value){WidgetRules.Enable(C.Prefs.Widgets,kind,value);Notes.Flush();C.Save();Store.Trace("WIDGET COMMAND kind="+kind+" enabled="+value);QueueSync();}
        public void Closed(WidgetWindow window,bool disable){if(!windows.Remove(window.PanelId,window))return;if(!closed&&!C.ShuttingDown&&Application.Current!=null&&!Application.Current.Dispatcher.HasShutdownStarted){Store.Trace("WIDGET WINDOW CLOSED; keep enabled panel="+window.PanelId);if(disable)QueueSync();}}
        public void Dispose(){closed=true;timer.Stop();if(island!=null){island.Close();island=null;}foreach(var notice in reminderWindows.ToList())notice.Close();foreach(var w in windows.Values){windows.Remove(w.PanelId,w);TryStop(w);}try{Notes.Dispose();}finally{Weather.Stop();if(Music!=null){var old=Music;Music=null;old.Dispose();}}}
    }
