        void Clock(StackPanel parent){clock=new TextBlock{FontSize=48,FontWeight=FontWeights.Light,Foreground=TextBrush};date=new TextBlock{FontSize=12,Foreground=MutedBrush,Margin=new Thickness(3,5,0,0)};clockStatus=new TextBlock{FontSize=11,Foreground=MutedBrush,Margin=new Thickness(3,9,0,0),TextTrimming=TextTrimming.CharacterEllipsis};var body=new StackPanel{Background=Brushes.Transparent,Cursor=Cursors.SizeAll,ToolTip="拖动时间或日期移动组件；锁定时不可移动"};body.Children.Add(clock);body.Children.Add(date);body.Children.Add(clockStatus);body.MouseLeftButtonDown+=(s,e)=>{if(e.ClickCount!=1||M.C.Prefs.Widgets.Locked)return;e.Handled=true;try{DragMove();var area=DesktopWindowPolicy.WorkArea(this);Left=FeatureRules.Position(Left,area.Left,area.Width,Width);Top=FeatureRules.Position(Top,area.Top,area.Height,Height);var pos=M.C.Prefs.Widgets.Position(PanelId);pos.Left=Left;pos.Top=Top;M.C.Save();Backdrop(LightTheme);ApplyWidgetGlass();}catch(InvalidOperationException){}};parent.Children.Add(body);}
        void ClockSettings(){var o=M.C.Prefs.Widgets;var w=FeatureUi.Dialog("闹钟与倒计时",this,540,650);var root=new StackPanel{Margin=new Thickness(24)};w.Content=new ScrollViewer{Content=root,VerticalScrollBarVisibility=ScrollBarVisibility.Hidden};root.Children.Add(new TextBlock{Text="闹钟",FontSize=21,Margin=new Thickness(0,0,0,12)});var list=new ListBox{Height=150};root.Children.Add(list);Action fill=()=>{int selected=list.SelectedIndex;list.ItemsSource=o.Alarms.Select(a=>(a.Enabled?"开启  ":"关闭  ")+a.Hour.ToString("00")+":"+a.Minute.ToString("00")+" · "+(a.Daily?"每天":"单次")+" · "+a.Label).ToList();if(selected>=0&&selected<o.Alarms.Count)list.SelectedIndex=selected;};fill();var editRow=new WrapPanel{Margin=new Thickness(0,8,0,12)};root.Children.Add(editRow);editRow.Children.Add(FeatureUi.Button("开启 / 关闭",()=>{int i=list.SelectedIndex;if(i<0)return;var a=o.Alarms[i];a.Enabled=!a.Enabled;if(a.Enabled)a.DueLocal=ClockRules.Next(a.Hour,a.Minute,DateTime.Now);M.C.Save();fill();}));editRow.Children.Add(FeatureUi.Button("删除已选",()=>{int i=list.SelectedIndex;if(i<0)return;o.Alarms.RemoveAt(i);M.C.Save();fill();}));var entry=new WrapPanel();root.Children.Add(entry);var time=new TextBox{Text=DateTime.Now.AddMinutes(1).ToString("HH:mm"),Width=75,MinHeight=38,Margin=new Thickness(0,0,8,0)};var label=new TextBox{Text="闹钟",Width=180,MinHeight=38};entry.Children.Add(time);entry.Children.Add(label);var daily=new CheckBox{Content="每天重复",IsChecked=false,Margin=new Thickness(0,10,0,8)};root.Children.Add(daily);root.Children.Add(FeatureUi.Button("添加闹钟",()=>{DateTime parsed;if(!DateTime.TryParseExact(time.Text.Trim(),"HH:mm",System.Globalization.CultureInfo.InvariantCulture,System.Globalization.DateTimeStyles.None,out parsed)){MessageBox.Show(w,"请填写 24 小时制时间，例如 08:30。");return;}if(o.Alarms.Count>=50){MessageBox.Show(w,"最多添加 50 个闹钟。");return;}o.Alarms.Add(new ClockAlarm{Hour=parsed.Hour,Minute=parsed.Minute,Label=string.IsNullOrWhiteSpace(label.Text)?"闹钟":label.Text.Trim(),Daily=daily.IsChecked==true,DueLocal=ClockRules.Next(parsed.Hour,parsed.Minute,DateTime.Now)});M.C.Save();fill();}));root.Children.Add(new TextBlock{Text="倒计时",FontSize=21,Margin=new Thickness(0,22,0,10)});var countdown=new TextBlock{Margin=new Thickness(0,0,0,10)};root.Children.Add(countdown);var minutes=new TextBox{Text="5",Width=80,MinHeight=38,HorizontalAlignment=HorizontalAlignment.Left};root.Children.Add(minutes);root.Children.Add(new TextBlock{Text="分钟 · 1–1440",Margin=new Thickness(0,5,0,8)});var buttons=new WrapPanel();root.Children.Add(buttons);buttons.Children.Add(FeatureUi.Button("开始",()=>{int value;if(!int.TryParse(minutes.Text,out value)||value<1||value>1440){MessageBox.Show(w,"请输入 1 到 1440 分钟。");return;}ClockRules.Start(o,value*60,DateTime.UtcNow);M.C.Save();}));buttons.Children.Add(FeatureUi.Button("暂停 / 继续",()=>{if(o.TimerDueUtc.HasValue)ClockRules.Pause(o,DateTime.UtcNow);else ClockRules.Resume(o,DateTime.UtcNow);M.C.Save();}));buttons.Children.Add(FeatureUi.Button("取消",()=>{ClockRules.Cancel(o);M.C.Save();}));root.Children.Add(new TextBlock{Text="到时弹窗并播放系统提示音，可稍后 5 分钟再提醒。GlassBoard 需保持运行；隐藏时钟仍会提醒。",TextWrapping=TextWrapping.Wrap,FontSize=12,Margin=new Thickness(0,16,0,0)});var refresh=new DispatcherTimer{Interval=TimeSpan.FromSeconds(1)};refresh.Tick+=(s,e)=>countdown.Text=ClockRules.Display(o,DateTime.UtcNow);w.Closed+=(s,e)=>refresh.Stop();countdown.Text=ClockRules.Display(o,DateTime.UtcNow);refresh.Start();w.ShowDialog();Tick();}
        void Weather(StackPanel parent){
            var style=StyleFor("weather");bool simple=style.WeatherStyle==1;
            weatherPlace=new TextBlock{Foreground=TextBrush,FontSize=12,FontWeight=FontWeights.Medium,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,4),Visibility=!simple||style.WeatherShowPlace?Visibility.Visible:Visibility.Collapsed};parent.Children.Add(weatherPlace);
            if(simple){
                var layout=new Grid{Height=125};layout.RowDefinitions.Add(new RowDefinition());layout.RowDefinitions.Add(new RowDefinition());
                weatherTemperature=new TextBlock{Foreground=TextBrush,FontSize=54,FontWeight=FontWeights.Medium,HorizontalAlignment=HorizontalAlignment.Right,VerticalAlignment=VerticalAlignment.Center};layout.Children.Add(weatherTemperature);
                weatherIcon=new ContentControl{Content=WeatherSymbol("cloud"),Width=44,Height=44,HorizontalAlignment=HorizontalAlignment.Left,VerticalAlignment=VerticalAlignment.Center};Grid.SetRow(weatherIcon,1);layout.Children.Add(weatherIcon);parent.Children.Add(layout);
            }else{
                var row=new Grid();row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(60)});var text=new StackPanel();row.Children.Add(text);
                weatherTemperature=new TextBlock{Foreground=TextBrush,FontSize=43,FontWeight=FontWeights.Light,Margin=new Thickness(0,4,0,0)};text.Children.Add(weatherTemperature);weatherIcon=new ContentControl{Content=WeatherSymbol("cloud"),Width=44,Height=44};Grid.SetColumn(weatherIcon,1);row.Children.Add(weatherIcon);parent.Children.Add(row);
            }
            weatherDetails=new TextBlock{Foreground=TextBrush,FontSize=11,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,4,0,4),Visibility=!simple||style.WeatherShowDetails?Visibility.Visible:Visibility.Collapsed};parent.Children.Add(weatherDetails);
            weatherStatus=new TextBlock{Foreground=MutedBrush,FontSize=10,VerticalAlignment=VerticalAlignment.Center,TextWrapping=TextWrapping.Wrap,MaxHeight=56,TextTrimming=TextTrimming.CharacterEllipsis,Margin=new Thickness(0,0,0,4)};parent.Children.Add(weatherStatus);
            if(!simple){var foot=new Grid();var actions=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right};actions.Children.Add(Small("刷新",()=>M.Weather.Update(true),45));var provider=Small("天气来源",()=>System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(M.Weather.Snapshot!=null&&M.Weather.Snapshot.Provider=="wttr.in"?"https://wttr.in/":"https://open-meteo.com/"){UseShellExecute=true}),88);provider.FontSize=10;actions.Children.Add(provider);foot.Children.Add(actions);parent.Children.Add(foot);}
        }
        void Music(StackPanel parent){var hero=new Grid();hero.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(72)});hero.ColumnDefinitions.Add(new ColumnDefinition());cover=new Border{Width=72,Height=72,CornerRadius=new CornerRadius(16),Background=Polish.Card(LightTheme),Clip=new RectangleGeometry(new Rect(0,0,72,72),16,16)};hero.Children.Add(cover);var metadata=new StackPanel{Margin=new Thickness(14,2,0,0),VerticalAlignment=VerticalAlignment.Center};Grid.SetColumn(metadata,1);hero.Children.Add(metadata);musicTitle=new TextBlock{Foreground=TextBrush,FontSize=17,FontWeight=FontWeights.SemiBold,TextWrapping=TextWrapping.Wrap,MaxHeight=48,TextTrimming=TextTrimming.CharacterEllipsis};musicArtist=new TextBlock{Foreground=MutedBrush,FontSize=12,TextTrimming=TextTrimming.CharacterEllipsis,Margin=new Thickness(0,5,0,0)};metadata.Children.Add(musicTitle);metadata.Children.Add(musicArtist);parent.Children.Add(hero);
            var transport=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Center,Margin=new Thickness(0,8,0,3)};var previous=MusicGlyph("previous",()=>M.Music.Action("previous"),34,false);previous.ToolTip="上一首";transport.Children.Add(previous);play=MusicGlyph("play",()=>{if(M.Music.Local&&M.C.Prefs.Widgets.Playlist.Count==0)M.Music.Pick(this);else M.Music.Action("toggle");},44,true);play.ToolTip="播放 / 暂停";transport.Children.Add(play);var next=MusicGlyph("next",()=>M.Music.Action("next"),34,false);next.ToolTip="下一首";transport.Children.Add(next);parent.Children.Add(transport);musicStatus=new TextBlock{Foreground=MutedBrush,FontSize=10,TextWrapping=TextWrapping.Wrap,MaxHeight=42,TextTrimming=TextTrimming.CharacterEllipsis,Margin=new Thickness(0,4,0,0)};parent.Children.Add(musicStatus);
