        void Playlist(){if(M.Music==null)return;var w=FeatureUi.Dialog("播放列表",this,540,510);var root=new DockPanel{Margin=new Thickness(22)};w.Content=root;var tools=new WrapPanel();DockPanel.SetDock(tools,Dock.Bottom);root.Children.Add(tools);var list=new ListBox();root.Children.Add(list);Action fill=()=>{list.ItemsSource=null;list.ItemsSource=M.C.Prefs.Widgets.Playlist.Select(p=>System.IO.Path.GetFileNameWithoutExtension(p)).ToList();list.SelectedIndex=M.C.Prefs.Widgets.TrackIndex;};fill();tools.Children.Add(FeatureUi.Button("添加",()=>{M.Music.Pick(w,true);fill();}));tools.Children.Add(FeatureUi.Button("播放已选",()=>{if(list.SelectedIndex>=0)M.Music.Select(list.SelectedIndex);fill();}));tools.Children.Add(FeatureUi.Button("移除已选",()=>{if(list.SelectedIndex>=0)M.Music.Remove(list.SelectedIndex);fill();}));list.MouseDoubleClick+=(s,e)=>{if(list.SelectedIndex>=0)M.Music.Select(list.SelectedIndex);};w.ShowDialog();}
        void Notes(StackPanel parent){noteSearch=new TextBox{MinHeight=36,Margin=new Thickness(0,0,0,8),ToolTip="搜索标题或内容"};parent.Children.Add(noteSearch);noteSearch.TextChanged+=(s,e)=>FilterNotes();notePicker=new ComboBox{MinHeight=42,Margin=new Thickness(0,0,0,10),HorizontalContentAlignment=HorizontalAlignment.Stretch};var titleView=new FrameworkElementFactory(typeof(TextBlock));titleView.SetBinding(TextBlock.TextProperty,new System.Windows.Data.Binding("DisplayTitle"));titleView.SetValue(TextBlock.TextWrappingProperty,TextWrapping.Wrap);titleView.SetValue(TextBlock.ForegroundProperty,StyleInk("notes"));titleView.SetValue(TextBlock.FontSizeProperty,14.0);titleView.SetValue(FrameworkElement.MaxWidthProperty,Math.Max(80,Width-160));notePicker.ItemTemplate=new DataTemplate{VisualTree=titleView};parent.Children.Add(notePicker);noteTitle=new TextBox{FontSize=17,MaxLength=120,FontWeight=FontWeights.SemiBold,MinHeight=48,Padding=new Thickness(12,9,12,9),TextWrapping=TextWrapping.Wrap,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled,VerticalContentAlignment=VerticalAlignment.Center,Margin=new Thickness(0,0,0,10),ToolTip="备忘录标题"};parent.Children.Add(noteTitle);noteBody=new TextBox{Height=170,VerticalContentAlignment=VerticalAlignment.Top,AcceptsReturn=true,AcceptsTab=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Hidden,FontSize=14,ToolTip="随手记下想法，内容自动保存",Background=Polish.Color(LightTheme?"#72FFF6D8":"#703E3B35")};parent.Children.Add(noteBody);noteTitle.TextChanged+=(s,e)=>NoteEdited();noteBody.TextChanged+=(s,e)=>NoteEdited();notePicker.DropDownOpened+=(s,e)=>{M.Notes.Flush();notePicker.Items.Refresh();};notePicker.SelectionChanged+=(s,e)=>{if(editingNotes)return;var note=notePicker.SelectedItem as NoteItem;if(note!=null){M.Notes.Select(note.Id);LoadNote();}};var actions=new WrapPanel{Margin=new Thickness(0,10,0,0)};actions.Children.Add(Small("新建",()=>{M.Notes.Add();M.RefreshNotes();},51));actions.Children.Add(Small("置顶",()=>{M.Notes.TogglePin();M.RefreshNotes();},48));actions.Children.Add(Small("清单",()=>{noteBody.SelectedText="☐ ";noteBody.Focus();},51));actions.Children.Add(Small("导出",()=>{var save=new Microsoft.Win32.SaveFileDialog{FileName="备忘录.md",Filter="Markdown|*.md"};if(save.ShowDialog(this)==true)try{M.Notes.ExportMarkdown(save.FileName);}catch(Exception ex){MessageBox.Show(this,ex.Message,"导出失败");}},51));actions.Children.Add(Small("删除",()=>{if(MessageBox.Show(this,"删除这条备忘录？","GlassBoard",MessageBoxButton.YesNo)==MessageBoxResult.Yes){M.Notes.Remove();M.RefreshNotes();}},51));parent.Children.Add(actions);noteStatus=new TextBlock{Foreground=MutedBrush,FontSize=10,Margin=new Thickness(0,8,0,0)};parent.Children.Add(noteStatus);ReloadNotes();}
        void NoteEdited(){if(editingNotes||currentNote==null)return;bool titleChanged=currentNote.Title!=noteTitle.Text;currentNote.Title=noteTitle.Text;currentNote.Body=noteBody.Text;if(titleChanged){editingNotes=true;try{notePicker.Items.Refresh();}finally{editingNotes=false;}}M.Notes.Changed();if(noteStatus!=null)SetText(noteStatus,M.Notes.Status);FitContent();}
        public void ReloadNotes(){if(notePicker==null)return;editingNotes=true;notePicker.ItemsSource=null;notePicker.ItemsSource=M.Notes.Book.Items;notePicker.SelectedItem=M.Notes.Book.Selected;editingNotes=false;FilterNotes();LoadNote();}
        void FilterNotes(){if(notePicker==null)return;string query=noteSearch==null?"":noteSearch.Text.Trim();string selected=M.Notes.Book.SelectedId;editingNotes=true;if(query.Length==0)notePicker.ItemsSource=M.Notes.Book.Items;else notePicker.ItemsSource=M.Notes.Book.Items.Where(n=>LayoutRules.Matches(n.Title,query)||((n.Body??"").IndexOf(query,StringComparison.CurrentCultureIgnoreCase)>=0)).ToList();notePicker.SelectedItem=M.Notes.Book.Items.FirstOrDefault(n=>n.Id==selected);editingNotes=false;}
        void LoadNote(){editingNotes=true;currentNote=M.Notes.Book.Selected;noteTitle.Text=currentNote.Title;noteBody.Text=currentNote.Body;editingNotes=false;FitContent();}
        public void Tick(){if(clock!=null){ClockTick();}if(noteStatus!=null)SetText(noteStatus,M.Notes.Status);}
        public void UpdateWeather(){if(weatherTemperature==null)return;var snapshot=M.Weather.Snapshot;weatherTemperature.Text=snapshot==null?"—°":snapshot.Current.Temperature.ToString("0.#")+"°";weatherPlace.Text=snapshot==null?(string.IsNullOrWhiteSpace(M.C.Prefs.Widgets.City)?"选择你的城市":M.C.Prefs.Widgets.City):WeatherPresentation.Place(M.C.Prefs.Widgets.City,snapshot.Place);if(weatherIcon!=null)((ContentControl)weatherIcon).Content=WeatherSymbol(snapshot==null?"cloud":WeatherPresentation.Icon(snapshot.Current.Code,snapshot.Current.Description));weatherDetails.Text=snapshot==null?"":WeatherPresentation.Description(snapshot.Current.Code,snapshot.Current.Description)+"  ·  风速 "+snapshot.Current.Wind.ToString("0.#")+" km/h";weatherStatus.Text=M.Weather.Message;weatherStatus.Visibility=StyleFor("weather").WeatherStyle==1&&snapshot!=null?Visibility.Collapsed:Visibility.Visible;weatherStatus.ToolTip=M.Weather.Message;weatherPlace.ToolTip=weatherPlace.Text;FitContent();}
        public void UpdateMusic(){if(building||musicStatus==null||play==null||M.Music==null)return;var engine=M.Music;string currentSignature=engine.Title+"\n"+engine.Artist+"\n"+engine.Album+"\n"+engine.Status+"/"+engine.Playing+"/"+engine.Local+"/"+M.C.Prefs.Widgets.Playlist.Count;if(musicLayoutSignature==currentSignature&&object.ReferenceEquals(shownArtwork,engine.Artwork??engine.AppIcon))return;musicLayoutSignature=currentSignature;musicTitle.Text=engine.Title;musicTitle.ToolTip=engine.Title;musicArtist.Text=engine.Artist;musicArtist.ToolTip=engine.Album;musicStatus.Text=string.IsNullOrWhiteSpace(engine.Status)?engine.Local?"本地播放 · "+M.C.Prefs.Widgets.Playlist.Count+" 首":"系统媒体会话":engine.Status;musicStatus.ToolTip=engine.Status;if(!object.ReferenceEquals(shownArtwork,engine.Artwork??engine.AppIcon)||cover.Child==null){shownArtwork=engine.Artwork??engine.AppIcon;cover.Child=shownArtwork==null?Polish.Icon("music",Polish.Color("#E8EDFF"),34):new Image{Source=shownArtwork,Stretch=engine.Artwork==null?Stretch.Uniform:Stretch.UniformToFill};}if(shownPlaying!=engine.Playing){shownPlaying=engine.Playing;play.Content=TransportIcon(engine.Playing?"pause":"play",true);}FitContent();}
    }
